(function(){'use strict';
 const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let data=null,pending=false,error=false,production=null,productionPending=false,productionError=false;
 const names={input_audit:'입력 확인',association:'수익 연관성',controls:'규모·유동성 통제',regime_interaction:'국면 비교',economic_link:'이후 실적',execution_cost:'체결·비용'};
 const state={COMPUTED:'관측 완료',NOT_COMPUTED:'미계산',INSUFFICIENT_SUPPORT:'표본 부족'};
 const pct=v=>Number.isFinite(v)?(100*v).toFixed(2)+'%':'미산출';
 const number=v=>Number.isFinite(v)?v.toFixed(3):'미산출';
 const kst=v=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
 const lines=items=>`<ul>${(items||[]).map(x=>`<li>${h(typeof x==='string'?x:x.text)}</li>`).join('')}</ul>`;
 function validate(value){
  if(value.schema_version!=='public-research-v2-v1'||value.independent_oos_claim!==false||value.causal_identification!==false||value.gold_writes!==0||!Array.isArray(value.cases)||!Array.isArray(value.stages))throw Error('Invalid public scope');
  return value;
 }
 function load(rerender){if(pending||data||error)return;pending=true;fetch('./data/research-v2.json').then(r=>{if(!r.ok)throw Error('Missing');return r.json();}).then(v=>{data=validate(v);pending=false;rerender();}).catch(()=>{error=true;pending=false;rerender();});}
 function validateProduction(value){
  if(value.schema_version!=='public-production-v2-v1'||!Number.isFinite(Date.parse(value.generated_at))||value.oos_results_included!==false||value.performance_metrics_included!==false||value.production_lessons_included!==false||value.automatic_gold_publication!==false||value.legacy_campaigns_changed!==false||value.snapshot_kind!=='STATIC_PROCESS_METADATA_NOT_LIVE_RESULTS'||!Array.isArray(value.campaigns)||!Array.isArray(value.architecture)||!value.counts||Object.values(value.counts).some(x=>!Number.isSafeInteger(x)||x<0))throw Error('Invalid production metadata scope');
  return value;
 }
 function loadProduction(rerender){if(productionPending||production||productionError)return;productionPending=true;fetch('./data/production-v2.json').then(r=>{if(!r.ok)throw Error('Missing');return r.json();}).then(v=>{production=validateProduction(v);productionPending=false;rerender();}).catch(()=>{productionError=true;productionPending=false;rerender();});}
 function productionView(){
  if(!production)return `<section class="panel v2-production"><div class="eyebrow">CURRENT PRODUCTION PATH</div><h2>현재 신규 연구 연결 현황</h2><p>${productionError?'현재 실행 현황 요약을 불러오지 못했습니다. 아래의 과거 파일럿 결과로 현재 상태를 대신 판단하지 않습니다.':'신규 캠페인의 상태 메타데이터를 불러오고 있습니다.'}</p></section>`;
  const p=production,c=p.counts;
  const sessionNames={NOT_INITIALIZED:'호스트 세션 준비 전',ACTIVE:'호스트 진단·해석 대기 또는 진행',PENDING_RECONCILIATION:'실행 상태 확인 필요',ACTION_BUDGET_EXHAUSTED:'사전 지정 실행 예산 소진',STOPPED:'호스트 해석 종료 · 독립 검토 별도',DATA_REQUESTED_NOT_ACQUIRED:'추가 자료 요청 · 미확보',NEW_TEST_PENDING_REVIEW:'후속 실험 제안 · 미실행'};
  const campaignNames={OPEN:'연구 진행 중',AWAITING_IMPLEMENTATION:'구현 검증 대기',READY_FOR_CONFIRMATION:'별도 최종 검증 대기',REVEALED:'최종 판정 종료',CLOSED_NO_QUALIFIED:'다음 단계 대상 없이 종료',CLOSED_ABORTED:'중단',CLOSED_INVALIDATED_INPUT_IDENTITY:'입력 식별자 불일치로 종료',CLOSED_RETROSPECTIVE_ONLY:'과거 자료 연구로 종료',SUPERSEDED_BOUNDARY_POLICY:'이전 경계 정책'};
  const stages={ABORTED_BEFORE_REGISTRATION:'후보 등록 전에 중단',CAMPAIGN_FROZEN_NO_REGISTERED_CANDIDATE:'캠페인 동결 · 후보 등록 전',CANDIDATES_REGISTERED_NO_HANDOFF:'후보 등록 · 진단 전달 전',PARTIAL_HANDOFF:'일부 후보의 진단 전달자료 준비',HANDOFF_READY_HOST_PENDING_OR_ACTIVE:'진단 자료 준비 · 호스트 대기 또는 진행',HOST_STOPPED_REVIEW_SEPARATE:'호스트 해석 종료 · 교훈 검토는 별도'};
  return `<section class="panel v2-production"><div class="section-head"><div><span class="eyebrow">CURRENT PRODUCTION PATH · STATUS ONLY</span><h2>지금은 신규 연구 경로에 연결되어 있습니다</h2></div><a class="small-button" href="./data/production-v2.json" download>실행 현황 내려받기</a></div><p class="lede">기존 평가·승인 엔진은 유지하고, 같은 실행의 자료를 새 진단·기억 경로로 전달합니다. 정책: <strong>${p.policy_enabled?'신규 캠페인에 사용':'현재 비활성'}</strong>.</p>
  <div class="v2-production-counts">${[['캠페인 생성 기록',c.new_campaigns],['등록 후보',c.registered_candidates],['진단 전달자료',c.prepared_handoffs],['호스트 해석 종료',c.explicitly_stopped_sessions]].map(([label,value])=>`<div><span>${h(label)}</span><strong>${value}개</strong></div>`).join('')}</div><p class="chart-note">캠페인 ${c.new_campaigns}개 중 중단 기록 ${c.aborted_campaigns??'미수집'}개 · 후보가 등록된 캠페인 ${c.campaigns_with_registered_candidates??'미수집'}개. 캠페인 생성·사전검사는 완료된 팩터 연구나 새 승인으로 계산하지 않습니다.</p>
  <dl class="v2-status">${p.architecture.map(a=>`<dt>${h(a.name)}</dt><dd><strong>${h(a.status)}</strong><p>${h(a.note)}</p></dd>`).join('')}</dl>
  <h3>실제 실행 상태</h3>${p.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>캠페인</th><th>평가 절차</th><th>등록 / 전달</th><th>진단·해석</th></tr></thead><tbody>${p.campaigns.map(campaign=>`<tr><th><code>${h(campaign.campaign_id)}</code></th><td>${h(campaignNames[campaign.status]||'상태 확인 필요')}<br><small>${h(stages[campaign.process_stage]||'세부 단계 미수집')}</small></td><td>${campaign.registered_candidates} / ${campaign.handoffs.length}</td><td>${campaign.handoffs.length?campaign.handoffs.map(item=>`<div><code>${h(item.factor)}</code><br>${h(sessionNames[item.session.status]||'상태 확인 필요')}<br><small>시장별 ${h(item.markets.join(' · ')||'자료 미연결')} · 관측한 진단 ${item.session.diagnostics_observed}개</small></div>`).join(''):'진단 전달자료 없음'}</td></tr>`).join('')}</tbody></table></div>`:'<p>아직 이 정책으로 생성된 캠페인이 없습니다. 코드 연결과 실제 연구 완료는 다릅니다.</p>'}
  <p class="chart-note">${h(p.review_boundary)}</p><details class="v2-detail"><summary>이 현황의 확인 범위</summary><p>${h(p.source_boundary)}</p></details><p class="chart-note">정적 스냅샷 생성: ${h(kst(p.generated_at))} KST. 자동 갱신·상시 실행 서비스가 아니며 아래 파일럿과 구분합니다.</p></section>`;
 }
 function render(rerender){load(rerender);loadProduction(rerender);if(!data)return `${productionView()}<section class="panel"><h1>과거 파일럿</h1><p>${error?'검토된 공개 요약을 불러오지 못했습니다. 결과를 추정하지 않습니다.':'검토된 교훈과 실제 실행 기록을 불러오고 있습니다.'}</p></section>`;
  const d=data,m=d.memory_comparison;
  return `<div class="v2-page">${productionView()}<div class="page-heading"><div><div class="eyebrow">ARCHIVED SIX-CASE PILOT · ${h(d.as_of)}</div><h1>과거 파일럿: 진단에서 교훈까지</h1><p class="lede">아래는 여섯 기존 팩터로 새 절차를 시험한 당시 결과입니다. 위의 신규 연구 진행 상황과는 별개입니다.</p></div><a class="small-button" href="./data/research-v2.json" download>파일럿 검토 요약 내려받기</a></div>
  <div class="v2-boundary"><strong>기존 연구와 구분된 절차 시험</strong><p>${h(d.scope_note)}</p><p>새 팩터 승인·독립 OOS 검증·실전 성과가 아닙니다. 기존 승인 상태와 과거 교훈은 바꾸지 않았습니다.</p></div>
  <div class="three-grid v2-kpis"><article class="panel"><span>실데이터 정의</span><strong>${d.cases.length}개</strong><small>고정 순서 / 에이전트 선택을 같은 자료로 비교</small></article><article class="panel"><span>독립 검토한 교훈</span><strong>${d.reviewed_lessons}개</strong><small>검토 완료는 인과관계의 증명이 아닙니다</small></article><article class="panel"><span>신규 승인 / Gold 적재</span><strong>0 / 0</strong><small>진단은 승인 검사를 대신하지 않습니다</small></article></div>
  <section class="panel"><h2>어떻게 돌아가는가</h2><ol class="v2-flow">${[['계약 동결','수식·기간·자료·예산을 먼저 정함'],['다음 검사 선택','경쟁 설명을 구분할 근거를 요청'],['관측 기록','실패·자료 없음·표본 부족을 구분'],['독립 비평','인용과 해석, 남은 의문을 확인'],['범위 있는 기억','검토된 내용만 다음 연구에 참고']].map(x=>`<li><strong>${x[0]}</strong><span>${x[1]}</span></li>`).join('')}</ol><p>${h(d.autonomy_note)}</p></section>
  <section class="panel section-gap"><h2>고정 검사보다 나아졌나</h2><p><strong>${h(d.real_comparison.decision)}</strong></p><div class="table-wrap"><table><thead><tr><th>방식</th><th>명목 진단 단위</th><th>중대한 오류</th><th>중대한 누락</th><th>세부 설명 생략</th></tr></thead><tbody>${d.real_comparison.arms.map(a=>`<tr><th>${h(a.label)}</th><td>${a.nominal_units}</td><td>${a.material_errors}건</td><td>${a.material_omissions}건</td><td>${a.presentation_gaps}건</td></tr>`).join('')}</tbody></table></div><p class="chart-note">${h(d.real_comparison.limitations)}</p></section>
  <div class="section-head"><div><span class="eyebrow">SIX FROZEN DEFINITIONS</span><h2>무엇을 배웠나</h2></div></div><p>아래 통제 전후 IC는 같은 종목·월의 표본에서 비교했습니다. 업종 통제가 아닌 시장구분·규모·유동성 조정입니다.</p>
  <div class="v2-cases">${d.cases.map(c=>`<article class="panel v2-case"><header><span class="badge blue">${h(c.family_ko)}</span><h3>${h(c.title_ko)}</h3><code>${h(c.case_id)}</code></header><p class="v2-question">${h(c.question_ko)}</p><div class="v2-metrics"><div><span>월별 Rank IC</span><strong>${number(c.mean_rank_ic)}</strong></div><div><span>동일 표본 통제 후 IC</span><strong>${number(c.controlled_ic)}</strong></div><div><span>관측 신호월</span><strong>${h(c.months??'미산출')}</strong></div><div><span>유효 점수 비율</span><strong>${pct(c.signal_coverage)}</strong></div></div><p class="chart-note">위 값은 개발 구간의 월별 관측 연관성입니다. 전략 수익률·새 승인 점수가 아닙니다.</p>
  <div class="v2-lesson"><h4>${h(c.lesson.title_ko)}</h4>${lines(c.lesson.facts.slice(0,2))}<p>${h(c.lesson.interpretation)}</p>${c.lesson.facts.length>2?`<details class="v2-detail"><summary>나머지 관측 근거</summary>${lines(c.lesson.facts.slice(2))}</details>`:''}</div>
  <details class="v2-detail"><summary>검사 순서와 선택 이유</summary><ol>${c.actions.map(a=>`<li><strong>${h(names[a.diagnostic_id]||a.diagnostic_id)}</strong> <span class="badge neutral">${h(state[a.status]||a.status)}</span><p>${h(a.reason)}</p></li>`).join('')}</ol><p>진단 비용 단위: 고정 ${c.fixed_units} / 선택 ${c.adaptive_units}. 등록된 도구 사용량이며 실제 원화 비용·전체 연구 효율과 다릅니다.</p></details>
  <details class="v2-detail"><summary>반대 설명 · 아직 모르는 점 · 다음 검사</summary><h4>아직 모르는 점</h4>${lines(c.lesson.unknowns)}<h4>경쟁 설명</h4>${lines(c.lesson.rivals)}<h4>다음 검사 — 제안이며 미실행</h4>${lines(c.lesson.next_tests)}<h4>적용 범위</h4><p>${h(c.lesson.scope_note)}</p><p>${h(c.lesson.limitations.join(' '))}</p><p class="chart-note">${h(c.lesson.evidence_note)}</p></details></article>`).join('')}</div>
  <div class="section-head"><div><span class="eyebrow">REGIME · LOOKBACK</span><h2>분류표보다 관측값을 먼저</h2></div></div><section class="panel"><p>${h(d.regime.note)}</p><div class="table-wrap"><table><thead><tr><th>시장</th><th>상승·저위험</th><th>상승·고위험</th><th>하락·저위험</th><th>하락·고위험</th><th>미분류</th></tr></thead><tbody>${d.regime.markets.map(r=>`<tr><th>${h(r.market)}</th>${['UP_LOW','UP_HIGH','DOWN_LOW','DOWN_HIGH','UNKNOWN'].map(k=>`<td>${r.counts[k]??0}개월</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="chart-note">${h(d.regime.limitations)}</p><p>${h(d.lookback_note)}</p></section>
  <div class="section-head"><div><span class="eyebrow">MEMORY COMPARISON · SYNTHETIC</span><h2>기억이 판단에 도움이 됐나</h2></div></div><section class="panel"><p>${h(m.scope_note)}</p><div class="table-wrap"><table><thead><tr><th>구성</th><th>판정 일치</th><th>근거 인용</th><th>원문 읽기</th><th>안전 위반</th></tr></thead><tbody>${m.arms.map(a=>`<tr><th>${h(a.label)}</th><td>${a.correct}/${a.cases}</td><td>${a.citation_supported}/${a.cases}</td><td>${a.evidence_reads}회</td><td>${a.safety_failures}건</td></tr>`).join('')}</tbody></table></div><p>${h(m.interpretation)}</p><p class="chart-note">${h(m.limitations)}</p></section>
  <div class="section-head"><div><span class="eyebrow">PILOT STATUS · NOT CURRENT PRODUCTION</span><h2>파일럿 당시 완료와 미검증의 경계</h2></div></div><section class="panel"><dl class="v2-status">${d.stages.map(s=>`<dt>${h(s.name)}</dt><dd><strong>${h(s.status_ko)}</strong><p>${h(s.note)}</p></dd>`).join('')}</dl><p>파일럿 공개 반영: ${h(d.as_of)}. 현재 신규 연구의 연결 현황은 이 페이지 맨 위에 별도로 표시합니다.</p></section></div>`;
 }
 window.ResearchV2UI=Object.freeze({render,validate,validateProduction,snapshotDate:()=>production?kst(production.generated_at).slice(0,10):data?.as_of||null});
})();
